const MarketValueAnimation: React.FC<MarketValueAnimationProps> = ({
  backgroundColor = "#041122",
  transparentBackground = false,
  durationInSeconds = 5,
  marketValueTitle = "MARKET VALUE",
  andText = "AND",
  replacementCostTitle = "REPLACEMENT COST",
  areDifferentText = "ARE DIFFERENT",
  marketValueAmount = 450000,
  replacementCostAmount = 650000,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Text Entrance Animations
  const text1Y = interpolate(spring({ frame: frame - 5, fps, config: { damping: 12 } }), [0, 1], [60, 0]);
  const text1Opacity = interpolate(frame, [5, 15], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  const text2Y = interpolate(spring({ frame: frame - 10, fps, config: { damping: 12 } }), [0, 1], [60, 0]);
  const text2Opacity = interpolate(frame, [10, 20], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  const text3Y = interpolate(spring({ frame: frame - 15, fps, config: { damping: 12 } }), [0, 1], [60, 0]);
  const text3Opacity = interpolate(frame, [15, 25], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  const text4Y = interpolate(spring({ frame: frame - 20, fps, config: { damping: 12 } }), [0, 1], [60, 0]);
  const text4Opacity = interpolate(frame, [20, 30], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  // Card Entrance Animations
  const card1Progress = spring({ frame: frame - 30, fps, config: { damping: 14, mass: 1.2 } });
  const card1Y = interpolate(card1Progress, [0, 1], [height * 0.5, 0]);
  const card1Opacity = interpolate(frame, [30, 40], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  const card2Progress = spring({ frame: frame - 40, fps, config: { damping: 14, mass: 1.2 } });
  const card2Y = interpolate(card2Progress, [0, 1], [height * 0.5, 0]);
  const card2Opacity = interpolate(frame, [40, 50], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  // Number Counter Animations
  const numProg = spring({ frame: frame - 55, fps, config: { damping: 15, mass: 1 } });
  const val1 = interpolate(numProg, [0, 1], [0, marketValueAmount]);
  const val2 = interpolate(numProg, [0, 1], [0, replacementCostAmount]);

  // Not Equal Symbol Animation
  const notEqProgress = spring({ frame: frame - 55, fps, config: { damping: 12, mass: 0.8 } });
  const notEqScale = interpolate(notEqProgress, [0, 1], [0, 1]);
  const notEqOpacity = interpolate(frame, [55, 60], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  const formatPrice = (value: number) => {
    const parts = Math.round(value).toString().split(".");
    parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    return '$' + parts.join(".");
  };

  const textBaseStyle: React.CSSProperties = {
    fontFamily: oswaldFamily,
    textAlign: 'center',
    lineHeight: 1,
    margin: 0,
    letterSpacing: '0.02em',
    textShadow: '0 6px 16px rgba(0,0,0,0.6)',
  };

  const cardWidth = width * 0.43;
  const cardHeight = height * 0.45;
  const borderRadius = 30 * s;
  const borderWidth = 10 * s;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Top Text Stack */}
      <div style={{
        position: 'absolute',
        top: height * 0.08,
        left: 0,
        width: '100%',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
      }}>
        <div style={{ ...textBaseStyle, color: '#81e6d9', fontSize: width * 0.12, transform: `translateY(${text1Y}px)`, opacity: text1Opacity, transition: "none" }}>
          {marketValueTitle}
        </div>
        <div style={{ ...textBaseStyle, color: '#ffffff', fontSize: width * 0.06, marginTop: height * 0.015, transform: `translateY(${text2Y}px)`, opacity: text2Opacity, transition: "none" }}>
          {andText}
        </div>
        <div style={{ ...textBaseStyle, color: '#90cdf4', fontSize: width * 0.1, marginTop: height * 0.015, transform: `translateY(${text3Y}px)`, opacity: text3Opacity, transition: "none" }}>
          {replacementCostTitle}
        </div>
        <div style={{ ...textBaseStyle, color: '#ffffff', fontSize: width * 0.12, marginTop: height * 0.015, transform: `translateY(${text4Y}px)`, opacity: text4Opacity, transition: "none" }}>
          {areDifferentText}
        </div>
      </div>

      {/* Cards Container */}
      <div style={{
        position: 'absolute',
        top: height * 0.42,
        left: 0,
        width: '100%',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        gap: width * 0.04,
      }}>
        
        {/* Left Card: Market Value */}
        <div style={{
          width: cardWidth,
          height: cardHeight,
          transform: `translateY(${card1Y}px)`,
          opacity: card1Opacity,
          backgroundColor: '#234e52',
          borderRadius: borderRadius,
          border: `${borderWidth}px solid #81e6d9`,
          display: 'flex',
          flexDirection: 'column',
          overflow: 'hidden',
          boxShadow: '0 24px 48px rgba(0,0,0,0.5)',
          transition: "none"
        }}>
          <div style={{ flex: '0 0 15%', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: '#234e52' }}>
            <span style={{ fontFamily: oswaldFamily, color: 'white', fontSize: width * 0.045, whiteSpace: 'nowrap' }}>{marketValueTitle}</span>
          </div>
          <div style={{ flex: '1 1 auto', position: 'relative', overflow: 'hidden' }}>
            <MarketValueHouse />
          </div>
          <div style={{ flex: '0 0 20%', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: '#234e52' }}>
            <span style={{ fontFamily: oswaldFamily, color: '#81e6d9', fontSize: width * 0.08, letterSpacing: '0.02em' }}>{formatPrice(val1)}</span>
          </div>
        </div>

        {/* Right Card: Replacement Cost */}
        <div style={{
          width: cardWidth,
          height: cardHeight,
          transform: `translateY(${card2Y}px)`,
          opacity: card2Opacity,
          backgroundColor: '#2a4365',
          borderRadius: borderRadius,
          border: `${borderWidth}px solid #90cdf4`,
          display: 'flex',
          flexDirection: 'column',
          overflow: 'hidden',
          boxShadow: '0 24px 48px rgba(0,0,0,0.5)',
          transition: "none"
        }}>
          <div style={{ flex: '0 0 15%', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: '#2a4365' }}>
            <span style={{ fontFamily: oswaldFamily, color: 'white', fontSize: width * 0.045, whiteSpace: 'nowrap' }}>{replacementCostTitle}</span>
          </div>
          <div style={{ flex: '1 1 auto', position: 'relative', overflow: 'hidden' }}>
            <ReplacementCostHouse />
          </div>
          <div style={{ flex: '0 0 20%', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: '#2a4365' }}>
            <span style={{ fontFamily: oswaldFamily, color: '#90cdf4', fontSize: width * 0.08, letterSpacing: '0.02em' }}>{formatPrice(val2)}</span>
          </div>
        </div>
      </div>

      {/* Not Equal Symbol */}
      <div style={{
        position: 'absolute',
        top: height * 0.42 + (cardHeight / 2),
        left: '50%',
        width: width * 0.08,
        height: width * 0.08,
        transform: `translate(-50%, -50%) scale(${notEqScale})`,
        opacity: notEqOpacity,
        transition: "none",
        filter: 'drop-shadow(0 10px 15px rgba(0,0,0,0.5))'
      }}>
        <svg viewBox="0 0 100 100" style={{ width: '100%', height: '100%', overflow: 'visible', display: 'block' }}>
          <line x1="15" y1="35" x2="85" y2="35" stroke="#ffffff" strokeWidth="12" strokeLinecap="round" />
          <line x1="15" y1="65" x2="85" y2="65" stroke="#ffffff" strokeWidth="12" strokeLinecap="round" />
          <line x1="75" y1="15" x2="25" y2="85" stroke="#ffffff" strokeWidth="12" strokeLinecap="round" />
        </svg>
      </div>

    </AbsoluteFill>
  );
};

export default MarketValueAnimation;